      .then(data => {
        if (data.length > 0) {
          setSessions(data);
          setActiveSessionId(data[0].id);
        } else {
          const def = makeDefaultSession(workspaceId);
          setSessions([def]);
          setActiveSessionId(def.id);
        }
      })
      .catch((err) => {
        console.error('[useSessions] fetch failed:', err);
        setError(err instanceof Error ? err.message : 'Failed to load');
        const def = makeDefaultSession(workspaceId);
        setSessions([def]);
        setActiveSessionId(def.id);
      })
      .finally

